declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';header('Content-Type: application/json; charset=utf-8');
function receipt_json(bool $ok,string $message,array $extra=[]): never {echo json_encode(array_merge(['ok'=>$ok,'message'=>$message],$extra),JSON_UNESCAPED_SLASHES);exit;}
function receipt_transaction_summary(int $periodId): array {
 $q=db()->prepare("SELECT COALESCE(c.category_name,'UNCATEGORIZED') category_name,SUM(t.amount) total,COUNT(*) item_count,SUM(CASE WHEN t.receipt_found=0 THEN 1 ELSE 0 END) missing_receipt_count,SUM(CASE WHEN t.category_id IS NULL OR t.receipt_found=0 THEN 1 ELSE 0 END) incomplete_count FROM management_receipt_transactions t LEFT JOIN management_receipt_categories c ON c.id=t.category_id LEFT JOIN management_receipt_analysis_runs r ON r.id=t.analysis_run_id WHERE t.management_receipt_period_id=? AND (r.is_current=1 OR t.analysis_run_id IS NULL) GROUP BY COALESCE(c.category_name,'UNCATEGORIZED')");$q->execute([$periodId]);$categoryTotals=[];$uncategorizedCount=0;$missingReceiptCount=0;$incompleteCount=0;$transactionCount=0;$breakdownTotal=0.0;foreach($q->fetchAll() as $row){$categoryName=(string)$row['category_name'];$total=(float)$row['total'];$count=(int)$row['item_count'];$categoryTotals[$categoryName]=$total;$transactionCount+=$count;$breakdownTotal+=$total;$missingReceiptCount+=(int)$row['missing_receipt_count'];$incompleteCount+=(int)$row['incomplete_count'];if($categoryName==='UNCATEGORIZED')$uncategorizedCount=$count;}return ['category_totals'=>$categoryTotals,'uncategorized_count'=>$uncategorizedCount,'missing_receipt_count'=>$missingReceiptCount,'incomplete_count'=>$incompleteCount,'transaction_count'=>$transactionCount,'breakdown_total'=>$breakdownTotal];
}
