 }
 if(($_POST['action']??'')==='add_payment'){
  if(!manage_receipt_payments_schema_ready())receipt_json(false,'Run the Management Properties upgrade before adding payments.');
  $paymentDate=trim((string)($_POST['payment_date']??''));$bankAccount=mb_substr(trim((string)($_POST['bank_account_paid_from']??'')),0,190);$amount=(float)str_replace([',','$'],'',(string)($_POST['amount_paid']??'0'));
  $date=DateTimeImmutable::createFromFormat('!Y-m-d',$paymentDate);if(!$date||$date->format('Y-m-d')!==$paymentDate||$bankAccount===''||$amount<=0)receipt_json(false,'Enter a valid payment date, bank account, and amount greater than zero.');
  db()->beginTransaction();db()->prepare("INSERT INTO management_receipt_periods(management_property_id,report_year,report_month,status,updated_by_admin_user_id) VALUES(?,?,?,'submitted',?) ON DUPLICATE KEY UPDATE updated_by_admin_user_id=VALUES(updated_by_admin_user_id)")->execute([$propertyId,$year,$month,(int)($managementUser['id']??0)]);$q=db()->prepare('SELECT id FROM management_receipt_periods WHERE management_property_id=? AND report_year=? AND report_month=?');$q->execute([$propertyId,$year,$month]);$periodId=(int)$q->fetchColumn();db()->prepare('INSERT INTO management_receipt_payments(management_receipt_period_id,payment_date,bank_account_paid_from,amount_paid,created_by_admin_user_id) VALUES(?,?,?,?,?)')->execute([$periodId,$paymentDate,$bankAccount,$amount,(int)($managementUser['id']??0)]);db()->commit();receipt_json(true,'Payment saved.');
 }
 if(($_POST['action']??'')==='delete_payment'){
  if(!manage_receipt_payments_schema_ready())receipt_json(false,'Payment records are not installed.');$paymentId=(int)($_POST['payment_id']??0);$q=db()->prepare('SELECT rp.id FROM management_receipt_payments rp JOIN management_receipt_periods p ON p.id=rp.management_receipt_period_id WHERE rp.id=? AND p.management_property_id=? AND p.report_year=? AND p.report_month=?');$q->execute([$paymentId,$propertyId,$year,$month]);if(!$q->fetchColumn())receipt_json(false,'Payment not found.');db()->prepare('DELETE FROM management_receipt_payments WHERE id=?')->execute([$paymentId]);receipt_json(true,'Payment deleted.');
