],$transaction['amount'],$transaction['source_line']]);$transactionCount++;}}db()->commit();
   $message=count($items)===1?'File uploaded.':'Files uploaded.';
   if($category==='statement'){if($parseFailed||$transactionCount===0)$message.=' No charge rows could be extracted automatically; the statement remains available for review.';else $message.=' '.$transactionCount.' charge'.($transactionCount===1?' was':'s were').' added to the breakdown.';try{$property=manage_property($propertyId);$monthName=DateTimeImmutable::createFromFormat('!m',(string)$month)->format('F');$subject='Credit Card Statement - '.$monthName.', '.$year;$body='<p>Please access portal at <a href="https://ZNPDEV.com">ZNPDEV.com</a> to upload your receipts and categorize the statement.</p>';$mail=app_send_mail_detailed((string)($property['gm_email']??''),$subject,$body,[]);if(!$mail['ok']){error_log('Receipt statement GM notification failed: '.$mail['error']);$message.=' The GM notification email could not be sent.';}else $message.=' The property GM was notified.';}catch(Throwable $mailError){error_log('Receipt statement GM notification failed: '.$mailError->getMessage());$message.=' The GM notification email could not be sent.';}}
   receipt_json(true,$message,['files'=>$items,'period_status'=>'submitted','transaction_count'=>$transactionCount]);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();foreach($uploads as $file)try{znp_storage_delete((string)$file['path']);}catch(Throwable $cleanup){}throw $e;}
 }
 if(($_POST['action']??'')==='analyze_statement'){
  if(!manage_is_admin())receipt_json(false,'Only a Super Admin may analyze statements.');$id=(int)($_POST['file_id']??0);
  $q=db()->prepare("SELECT f.*,p.management_property_id,p.report_year,p.report_month FROM management_receipt_files f JOIN management_receipt_periods p ON p.id=f.management_receipt_period_id WHERE f.id=? AND f.file_category='statement'");$q->execute([$id]);$file=$q->fetch();if(!$file||(int)$file['management_property_id']!==$propertyId)receipt_json(false,'Statement not found.');
