  db()->beginTransaction();db()->prepare('DELETE FROM management_receipt_transactions WHERE statement_file_id=?')->execute([$id]);db()->prepare('DELETE FROM management_receipt_analysis_runs WHERE statement_file_id=?')->execute([$id]);$total=array_sum(array_column($transactions,'amount'));db()->prepare('INSERT INTO management_receipt_analysis_runs(management_receipt_period_id,statement_file_id,is_current,analyzed_by_admin_user_id,transaction_count,total_amount) VALUES(?,?,1,?,?,?)')->execute([(int)$file['management_receipt_period_id'],$id,(int)($managementUser['id']??0),count($transactions),$total]);$runId=(int)db()->lastInsertId();$insert=db()->prepare('INSERT INTO management_receipt_transactions(management_receipt_period_id,statement_file_id,transaction_date,cardholder,card_last_four,transaction_type,analysis_run_id,description,amount,source_line) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($transactions as $transaction)$insert->execute([(int)$file['management_receipt_period_id'],$id,$transaction['date'],$transaction['cardholder'],$transaction['last_four'],$transaction['type'],$runId,$transaction['description'],$transaction['amount'],$transaction['source_line']]);db()->commit();receipt_json(true,count($transactions).' line item'.(count($transactions)===1?' was':'s were').' saved. The previous analysis was replaced.',['transaction_count'=>count($transactions)]);
