 if(($_POST['action']??'')==='save_transaction'){
  $transactionId=(int)($_POST['transaction_id']??0);$notes=mb_substr(trim((string)($_POST['notes']??'')),0,5000);$categoryId=(int)($_POST['category_id']??0);$receiptFound=(int)($_POST['receipt_found']??0)===1?1:0;$q=db()->prepare('SELECT t.id,t.management_receipt_period_id,p.management_property_id,p.report_year,p.report_month FROM management_receipt_transactions t JOIN management_receipt_periods p ON p.id=t.management_receipt_period_id WHERE t.id=?');$q->execute([$transactionId]);$transaction=$q->fetch();if(!$transaction||(int)$transaction['management_property_id']!==$propertyId||(int)$transaction['report_year']!==$year||(int)$transaction['report_month']!==$month)receipt_json(false,'Line item not found.');if(!manage_is_admin()&&manage_receipt_period_sent_to_cpa((int)$transaction['management_property_id'],(int)$transaction['report_year'],(int)$transaction['report_month']))receipt_json(false,'This receipt breakdown was sent to the CPA and is locked. Only a Super Admin may change it.');if($categoryId>0){$q=db()->prepare('SELECT 1 FROM management_receipt_categories WHERE id=? AND is_active=1');$q->execute([$categoryId]);if(!$q->fetchColumn())receipt_json(false,'Invalid category.');}db()->prepare('UPDATE management_receipt_transactions SET category_id=?,receipt_found=?,notes=? WHERE id=?')->execute([$categoryId?:null,$receiptFound,$notes,$transactionId]);receipt_json(true,'Line item saved.',receipt_transaction_summary((int)$transaction['management_receipt_period_id']));
