 if(($_POST['action']??'')==='delete_transaction'){
  if(!manage_is_admin())receipt_json(false,'Only a Super Admin may remove analyzed line items.');$transactionId=(int)($_POST['transaction_id']??0);$q=db()->prepare('SELECT t.id,t.analysis_run_id,t.management_receipt_period_id,p.management_property_id,p.report_year,p.report_month FROM management_receipt_transactions t JOIN management_receipt_periods p ON p.id=t.management_receipt_period_id WHERE t.id=?');$q->execute([$transactionId]);$transaction=$q->fetch();if(!$transaction||(int)$transaction['management_property_id']!==$propertyId||(int)$transaction['report_year']!==$year||(int)$transaction['report_month']!==$month)receipt_json(false,'Line item not found.');db()->beginTransaction();db()->prepare('DELETE FROM management_receipt_transactions WHERE id=?')->execute([$transactionId]);if((int)($transaction['analysis_run_id']??0)>0){$q=db()->prepare('SELECT COUNT(*),COALESCE(SUM(amount),0) FROM management_receipt_transactions WHERE analysis_run_id=?');$q->execute([(int)$transaction['analysis_run_id']]);[$count,$total]=$q->fetch(PDO::FETCH_NUM);db()->prepare('UPDATE management_receipt_analysis_runs SET transaction_count=?,total_amount=? WHERE id=?')->execute([(int)$count,(float)$total,(int)$transaction['analysis_run_id']]);}$summary=receipt_transaction_summary((int)$transaction['management_receipt_period_id']);db()->commit();receipt_json(true,'Line item removed.',$summary);
 }
 if(($_POST['action']??'')==='categorize_file'){
